{% extends "base.html" %}
{% block title %}Pracownicy - {{ app_name }}{% endblock %}
{% block extra_css %}
<style>
:root{--color-ink:#1a1a1a;--color-ink-muted:#525252;--color-ink-subtle:#8a8a8a;--color-surface:#fafafa;--color-surface-warm:#f7f6f3;--color-border:#e8e6e1;--color-border-subtle:#f0eeea;--color-success:#2d6a4f;--font-display:'Inter',system-ui,sans-serif;--ease-out-expo:cubic-bezier\(0.16,1,0.3,1\)}
