.status-badge.active{background:rgba\(45,106,79,0.08\);color:var\(--color-success\)}.status-badge.inactive{background:rgba\(107,114,128,0.08\);color:#4b5563}
.action-link{color:#2563eb;font-size:0.8125rem;text-decoration:none}.action-link:hover{color:#1d4ed8}.action-link.secondary{color:var\(--color-ink-muted\)}.action-link.secondary:hover{color:var\(--color-ink\)}
