.material-icons{font-size:1rem;vertical-align:middle}.material-icons.lg{font-size:1.5rem}.fade-in{animation:fadeIn 0.4s var\(--ease-out-expo\)}@keyframes fadeIn{from{opacity:0;transform:translateY\(8px\)}to{opacity:1;transform:translateY\(0\)}}
@media \(max-width:768px\){.page-header{flex-direction:column;align-items:flex-start;gap:1rem}.stats-grid{grid-template-columns:1fr}}
</style>
{% endblock %}
{% block content %}
<div class="refined-page fade-in">
    <header class="page-header">
        <div><h1 class="page-title">Pracownicy</h1><p class="page-subtitle">Zarządzanie personelem salonu</p></div>
        <a href="{{ url_for\('main.create_employee'\) }}" class="refined-btn-primary"><span class="material-icons">add</span>Dodaj pracownika</a>
    </header>
    <div class="stats-grid">
        <div class="stat-card"><div><p class="stat-label">Wszyscy</p><p class="stat-value" id="stat-total">-</p></div><div class="stat-icon blue"><span class="material-icons lg">people</span></div></div>
        <div class="stat-card"><div><p class="stat-label">Aktywni</p><p class="stat-value green" id="stat-active">-</p></div><div class="stat-icon green"><span class="material-icons lg">check_circle</span></div></div>
        <div class="stat-card"><div><p class="stat-label">Zatrudnieni</p><p class="stat-value purple" id="stat-employed">-</p></div><div class="stat-icon purple"><span class="material-icons lg">work</span></div></div>
    </div>
    <div class="search-card"><div class="search-wrapper"><input type="text" id="search-input" placeholder="Szukaj po imieniu, nazwisku, telefonie lub emailu..." class="refined-input"><button onclick="loadEmployees\(\)" class="refined-btn-secondary"><span class="material-icons">search</span>Szukaj</button></div></div>
    <div class="table-container"><table class="refined-table"><thead><tr><th>Imię i nazwisko</th><th>Stanowisko</th><th>Telefon</th><th>Email</th><th>Status</th><th>Akcje</th></tr></thead><tbody id="employees-tbody"><tr><td colspan="6" class="empty-state"><span class="material-icons empty-icon">people</span><p class="empty-text">Ładowanie pracowników...</p></td></tr></tbody></table></div>
</div>
{% endblock %}
{% block extra_scripts %}
<script>
function escapeHtml\(t\){const m={'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'};return String\(t\).replace\(/[&<>"']/g,x=>m[x]\)}
async function loadStatistics\(\){try{const r=await fetch\('/api/employees/statistics'\);const d=await r.json\(\);if\(d.success\){document.getElementById\('stat-total'\).textContent=d.statistics.total_employees||0;document.getElementById\('stat-active'\).textContent=d.statistics.active_employees||0;document.getElementById\('stat-employed'\).textContent=d.statistics.employed||0;}}catch\(e\){console.error\(e\);}}
async function loadEmployees\(\){const q=document.getElementById\('search-input'\).value.trim\(\);const tbody=document.getElementById\('employees-tbody'\);try{const url=q?`/api/employees?search=${encodeURIComponent\(q\)}`:'/api/employees';const r=await fetch\(url\);const d=await r.json\(\);if\(d.success\){if\(d.employees.length===0\){tbody.innerHTML='<tr><td colspan="6" class="empty-state"><span class="material-icons empty-icon">search_off</span><p class="empty-text">Nie znaleziono pracowników</p></td></tr>';return;}tbody.innerHTML=d.employees.map\(e=>{const initials=escapeHtml\(e.first_name.charAt\(0\)+e.last_name.charAt\(0\)\);const fullName=escapeHtml\(e.full_name\);const phone=e.phone?escapeHtml\(e.phone\):'<span style="color:var\(--color-ink-subtle\)">—</span>';const email=e.email?escapeHtml\(e.email\):'<span style="color:var\(--color-ink-subtle\)">—</span>';const position=e.position?escapeHtml\(e.position\):'<span style="color:var\(--color-ink-subtle\)">—</span>';const statusBadge=e.is_active?'<span class="status-badge active">Aktywny</span>':'<span class="status-badge inactive">Nieaktywny</span>';return`<tr><td><div class="employee-info"><div class="employee-avatar">${initials}</div><div><div class="employee-name">${fullName}</div>${e.position?`<div class="employee-position">${escapeHtml\(e.position\)}</div>`:''}</div></div></td><td>${position}</td><td>${phone}</td><td>${email}</td><td>${statusBadge}</td><td style="text-align:right;"><a href="/employee/${e.id}" class="action-link">Zobacz</a><span style="margin:0 0.5rem;color:var\(--color-border\);">|</span><a href="/employee/${e.id}/edit" class="action-link secondary">Edytuj</a></td></tr>`;}\).join\(''\);}else{tbody.innerHTML=`<tr><td colspan="6" class="empty-state"><p class="empty-text" style="color:#9b2c2c;">Błąd: ${escapeHtml\(d.error\)}</p></td></tr>`;}}catch\(e\){tbody.innerHTML='<tr><td colspan="6" class="empty-state"><p class="empty-text" style="color:#9b2c2c;">Błąd połączenia z serwerem</p></td></tr>';}}
document.getElementById\('search-input'\).addEventListener\('keypress',e=>{if\(e.key==='Enter'\)loadEmployees\(\);}\);
document.addEventListener\('DOMContentLoaded',\(\)=>{loadStatistics\(\);loadEmployees\(\);}\);
</script>
{% endblock %}
TEMPLATE_EOF)
